bounded_host_request.command:
set -euo pipefail
cd "$HOME/Project/Gserver/projects/TGtumbler/GateApp-Bot"
python3 - <<'PY'
import json,subprocess,os,sys,time
from pathlib import Path
base=Path("deploy/state")
CHAT=-1002373696859
files={
4291:base/"startless-recover-missing-topic4291-20261122-retry1.json",
4672:base/"startless-recover-missing-topic4672-20261122.json",
}
def run(args,input=None,timeout=110):
 return subprocess.run(args,input=input,text=True,capture_output=True,timeout=timeout)
def query(sql):
 p=run(["docker","exec","deploy-postgres-1","psql","-X","-q","-v","ON_ERROR_STOP=1","-U","gace","-d","gaybbs","-Atc",sql],timeout=30)
 if p.returncode:raise RuntimeError("DB_COMMAND_FAILED")
 return p.stdout.strip()
def audit(topic):
 p=run(["python3","scripts/userbot_topic_audit_client.py","--chat-id",str(CHAT),"--topic-id",str(topic)],timeout=125)
 if p.returncode:raise RuntimeError("RESIDENT_AUDIT_FAILED")
 docs=[json.loads(x.split("=",1)[1]) for x in p.stdout.splitlines() if x.startswith("USERBOT_TOPIC_AUDIT=")]
 if len(docs)!=1 or len(docs[0].get("rows",[]))!=1:raise RuntimeError("AUDIT_SHAPE")
 return docs[0]["rows"][0]
def persist(path,obj,first=False):
 p=path if first else path.with_suffix(".next")
 with os.fdopen(os.open(p,os.O_CREAT|os.O_EXCL|os.O_WRONLY,0o600),"w") as f:
  json.dump(obj,f,ensure_ascii=False,sort_keys=True);f.flush();os.fsync(f.fileno())
 if not first:os.replace(p,path)
def call_bot(task):
 node=r"""
'use strict';
const fs=require('node:fs'),https=require('node:https');
const token=fs.readFileSync(process.env.BOT_TOKEN_FILE||'/run/secrets/bot_token','utf8').trim();
const t=__TASK_JSON__;
const agent=new https.Agent({keepAlive:false,family:4,timeout:20000});
function api(method,data){return new Promise((resolve,reject)=>{
 const body=JSON.stringify(data);
 const req=https.request({hostname:'api.telegram.org',path:'/bot'+token+'/'+method,method:'POST',agent,timeout:25000,headers:{'content-type':'application/json','content-length':Buffer.byteLength(body)}},res=>{
 let s='';res.on('data',c=>{if(s.length<16000)s+=c});res.on('end',()=>{try{const x=JSON.parse(s);resolve(x.ok===true?{ok:true,result:x.result}:{ok:false,code:x.error_code})}catch{reject(Error('RESPONSE_INVALID'))}})});
 req.on('error',()=>reject(Error('TRANSPORT_UNCERTAIN')));req.on('timeout',()=>req.destroy(Error('TIMEOUT_UNCERTAIN')));req.end(body);
})}
(async()=>{
 const me=await api('getMe',{});
 if(!me.ok||me.result.username?.toLowerCase()!=='gaybbs_bot'||me.result.id===8086265383)throw Error('BOT_IDENTITY_INVALID');
 const edit=await api('editMessageText',{chat_id:t.chat,message_id:t.message_id,text:'このトピックには投稿メニューボタンを設置していません。'});
 if(!edit.ok){console.log(JSON.stringify({state:'EDIT_REJECTED',code:edit.code}));process.exitCode=2;return;}
 const pin=await api('unpinChatMessage',{chat_id:t.chat,message_id:t.message_id});
 console.log(JSON.stringify({state:pin.ok?'BUTTON_REMOVED_UNPINNED':'BUTTON_REMOVED_UNPIN_UNCONFIRMED',code:pin.ok?null:pin.code}));
 if(!pin.ok)process.exitCode=3;
})().catch(e=>{console.log(JSON.stringify({state:'UNKNOWN',code:String(e.message||'UNKNOWN').replace(/[^A-Z_]/g,'').slice(0,50)}));process.exitCode=4});
"""
 p=run(["docker","exec","-i","deploy-gaybbs-1","node","-"],input=node.replace("__TASK_JSON__",json.dumps(task)),timeout=90)
 try:
  a=[json.loads(x) for x in p.stdout.splitlines() if x.startswith("{")]
  return p.returncode,a[0] if len(a)==1 else {"state":"UNKNOWN"}
 except:return p.returncode,{"state":"UNKNOWN"}
if run(["systemctl","--user","is-active","gace-userbot-verify.service"]).stdout.strip()!="active":raise SystemExit(60)
if run(["docker","inspect","-f","{{.State.Running}}","deploy-gaybbs-1"]).stdout.strip()!="true":raise SystemExit(61)
for topic,source in files.items():
 old=json.loads(source.read_text())
 if old.get("state")!="VERIFIED":raise SystemExit(62)
 mid=old.get("message_id")
 if not isinstance(mid,int) or mid<1:raise SystemExit(63)
 f=base/f"startless-recover-missing-topic{topic}-20261122-withdrawn.json"
 if f.exists():raise SystemExit(64)
 if query(f"SELECT message_id,state,pinned FROM topic_dm_entry_pins WHERE chat_id={CHAT} AND message_thread_id={topic}")!=f"{mid}|published|t":raise SystemExit(65)
 row=audit(topic)
 if row.get("post_button")!="PRESENT" or mid not in row.get("pin_message_ids",[])+row.get("history_message_ids",[]):raise SystemExit(66)
 persist(f,{"state":"WITHDRAWAL_ATTEMPTING","topic_id":topic,"message_id":mid,"source":"new_post_only"},first=True)
 code,result=call_bot({"chat":CHAT,"message_id":mid})
 state=result.get("state","UNKNOWN")
 if code or state!="BUTTON_REMOVED_UNPINNED":
  persist(f,{"state":state,"topic_id":topic,"message_id":mid})
  raise SystemExit(67)
 changed=query(f"UPDATE topic_dm_entry_pins SET state='needs_reconcile',pinned=FALSE,updated_at=NOW() WHERE chat_id={CHAT} AND message_thread_id={topic} AND message_id={mid} AND state='published' AND pinned=TRUE RETURNING message_id")
 if changed!=str(mid):
  persist(f,{"state":"DB_DISABLE_UNCONFIRMED","topic_id":topic,"message_id":mid})
  raise SystemExit(68)
 persist(f,{"state":"DISABLED_BY_MASTER","topic_id":topic,"message_id":mid,"new_post_retained":True,"inline_keyboard_removed":True,"unpinned":True})
 for i in range(3):
  row=audit(topic)
  if row.get("post_button")=="ABSENT" and mid not in row.get("pin_message_ids",[]):
   persist(f,{"state":"VERIFIED_DISABLED_BY_MASTER","topic_id":topic,"message_id":mid,"new_post_retained":True,"inline_keyboard_removed":True,"unpinned":True})
   break
  if i<2:time.sleep(2)
 else:raise SystemExit(69)
 print(f"VIDEO_TOPIC_{topic}_EXTRA_BUTTON_REMOVED=VERIFIED")
if run(["systemctl","--user","is-active","gace-userbot-verify.service"]).stdout.strip()!="active":raise SystemExit(70)
print("NO_ORIGINAL_MESSAGES_DELETED=PASS")
PY
